            v = first_val[k]
            print(f'  {k} type={type(v)}, len={len(v) if hasattr(v,\"__len__\") else \"N/A\"}')
            if isinstance(v, list) and len(v) > 0:
                print(f'  first item: {v[0]}')
            elif isinstance(v, dict):
                fk = list(v.keys())[:3]
                print(f'  first keys: {fk}')
                for fkk in fk:
                    print(f'    {fkk}: {v[fkk]}')
    # If no known key, print all
    if not any(k in first_val for k in ['results', 'tasks', 'episodes', 'task_results']):
        for k, v in list(first_val.items())[:5]:
            print(f'  {k}: {type(v)} = {str(v)[:200]}')
